insert into transmission_units (code, family, reliability_note) values ('generic:8-speed dct', 'dct', 'Generic bucket — the specific dual-clutch unit isn''t identifiable from this data. Watch-item for any DCT: dry-clutch types can show low-speed judder/hesitation in stop-go traffic; wet-clutch types are generally smoother but fluid service still matters. Ask which type (dry/wet) if possible.');
insert into transmission_units (code, family, reliability_note) values ('generic:Single-speed EV (dual motor)', 'single_speed', 'Generic bucket — the specific reduction-gear unit isn''t identifiable from this data. Single-speed EV reducer — one fixed gear, no clutch or torque converter, so there is no traditional gearbox fault pattern. Very low maintenance. Any drivetrain issues are typically electronics/motor-related, not the reduction gear.');
insert into transmission_units (code, family, reliability_note) values ('generic:e-Power Fixed Ratio', 'single_speed', 'Generic bucket — specific unit not identifiable. Series-hybrid / fixed-ratio drive: the wheels are driven by an electric motor through a fixed reduction (no clutch or multi-speed gearbox to wear), so there''s no traditional gearbox fault pattern. It does have a petrol engine acting as a generator — so engine/hybrid-system health matters, even though the drive unit itself is simple.');
insert into transmission_units (code, family, reliability_note) values ('generic:7-speed Manual', 'manual', 'Generic bucket — the specific gearbox unit isn''t identifiable from this data. Simple, durable design with no gearbox-specific fault pattern. The clutch is a normal wear item, not a fault — on a used car, check for clutch judder, a high biting point, or crunchy/notchy shifts (especially 2nd gear) on the test drive. Bearing/synchro whine can appear at very high mileage.');
