-- Path B Step 1 (revised): populate transmission_units from
-- scripts/transmission-faults-template.csv — now covers all 65 groups.
--
-- PREREQUISITE: run the constraint ALTER in
-- scripts/alter-transmission-units-family-constraint.sql FIRST — this file's 3
-- generic-DCT inserts use family = 'dct' ('dual-clutch, dry/wet unspecified'),
-- which the ORIGINAL constraint rejects. Do not run this file before that one.
--
-- code = unit_code_or_type (generic groups prefixed 'generic:' per the requested convention).
-- family = the CSV's family column. reliability_note = the authored NEW_FAULTS text.
-- maintenance_note intentionally left NULL — a later pass fills it in.
-- The 2 already-seeded rows (VW DQ200, ZF 8HP) are UPDATEd, not re-inserted — their sample
-- 'SAMPLE — replace.' reliability_note is superseded by the authored text below.
-- Review before running. NOT executed against Supabase. No car linking (unit_id) here.

update transmission_units set reliability_note = 'Very robust; one of the best autos made. Main watch-item is the "sealed for life" fluid myth: skip the ~80–100k km service and you get valve-body/mechatronic wear and harsh shifts. Some early cars had torque-converter lock-up shudder. RAM''s 8HP75 shares the same profile.' where code = 'ZF 8HP';
update transmission_units set reliability_note = 'The problem child of this list. Mechatronic failures (early units had the synthetic oil in the mechatronic degrading, causing pressure/electrical faults; later it''s the valve body/accumulator) plus dry-clutch judder and premature clutch wear — worst in stop-go city traffic, exactly your Bratislava DCT concern. Subject to warranty extensions in several markets.' where code = 'VW DQ200';
